window.OPEN_SHELF_KNOWLEDGE = {"updatedAt":"2026-10-11","sourceCommit":"bd8f81ddb5c74d5c8897b36ad88b440266245103","articles":[{"title":"Abugidas & alphasyllabary","slug":"glossary-abugidas-alphasyllabary","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A writing system that combines consonants and vowels into a singular unit, with the consonant being the primary element, and the vowel secondary.","url":"articles/glossary-abugidas-alphasyllabary/","image":"articles/media/glossary/terms/abugidas_alphasyllabary/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/abugidas_alphasyllabary"},{"title":"Alignment & justification","slug":"glossary-alignment-justification","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"In paragraphs of (western) text, alignment refers to the invisible vertical line implied by a block of type. Justified text is aligned to both left and right margins.","url":"articles/glossary-alignment-justification/","image":"articles/media/glossary/terms/alignment_justification/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/alignment_justification"},{"title":"All-caps","slug":"glossary-all-caps","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Text set entirely in uppercase letters.","url":"articles/glossary-all-caps/","image":"articles/media/glossary/terms/all_caps/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/all_caps"},{"title":"Alphabet","slug":"glossary-alphabet","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A writing system in which the elemental speech sounds of a language are represented by a set of graphical units, called letters.","url":"articles/glossary-alphabet/","image":"articles/media/glossary/terms/alphabet/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/alphabet"},{"title":"Alternates","slug":"glossary-alternates","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Alternates (also known as alternate characters or alternate glyphs) are substitute letterforms that supplement the default character set.","url":"articles/glossary-alternates/","image":"articles/media/glossary/terms/alternates/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/alternates"},{"title":"Ampersand (&)","slug":"glossary-ampersand","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A character for “and,“ originally serving as a ligature for “et“ (the Latin word for “and”). Its name is derived from the phrase “and per se and”.","url":"articles/glossary-ampersand/","image":"articles/media/glossary/terms/ampersand/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/ampersand"},{"title":"AR Retinal Resolution axis (ARRR)","slug":"glossary-arrr-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to optimize text rendering across different resolutions.","url":"articles/glossary-arrr-axis/","image":"articles/media/glossary/terms/arrr_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/arrr_axis"},{"title":"Ascenders & descenders","slug":"glossary-ascenders-descenders","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The upward or downward parts of letterforms that extend above the x-height—and usually above the cap height (ascenders)—and drop below the baseline (descenders).","url":"articles/glossary-ascenders-descenders/","image":"articles/media/glossary/terms/ascenders_descenders/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/ascenders_descenders"},{"title":"Axis (in type design)","slug":"glossary-axis-in-type-design","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The angle of the “pen” in a letterform, usually implied by the contrast of a stroke.","url":"articles/glossary-axis-in-type-design/","image":"articles/media/glossary/terms/axis_in_type_design/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/axis_in_type_design"},{"title":"Axis (in variable fonts)","slug":"glossary-axis-in-variable-fonts","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A single aspect of a typeface’s design that can be altered by the user, such as weight, width, slant, or optical size.","url":"articles/glossary-axis-in-variable-fonts/","image":"articles/media/glossary/terms/axis_in_variable_fonts/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/axis_in_variable_fonts"},{"title":"Baseline","slug":"glossary-baseline","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The invisible line upon which a line of type rests. It’s used as a point from which other elements are measured, such as leading (line height) and x-height.","url":"articles/glossary-baseline/","image":"articles/media/glossary/terms/baseline/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/baseline"},{"title":"Bespoke, or custom type","slug":"glossary-bespoke-custom-type","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Type specifically commissioned by a client, usually to serve as a brand typeface. It's not normally not available to the public.","url":"articles/glossary-bespoke-custom-type/","image":"articles/media/glossary/terms/bespoke_custom_type/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/bespoke_custom_type"},{"title":"Blackletter","slug":"glossary-blackletter","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A historical classification that relates to typefaces that initially arose—and/or became popular in—medieval Europe.","url":"articles/glossary-blackletter/","image":"articles/media/glossary/terms/blackletter/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/blackletter"},{"title":"Bleed axis (BLED)","slug":"glossary-bled-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to adjust the text’s overall darkness or typographic color by altering its glyphs’ shapes such as strokes.","url":"articles/glossary-bled-axis/","image":"articles/media/glossary/terms/bled_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/bled_axis"},{"title":"Bounce axis (BNCE)","slug":"glossary-bnce-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to reposition letterforms vertically, away from the baseline, creating a more handwritten or organic style.","url":"articles/glossary-bnce-axis/","image":"articles/media/glossary/terms/bnce_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/bnce_axis"},{"title":"Body","slug":"glossary-body","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Either the main text in a piece of content, or the “body” optical size (which serves as the opposite of “display”).","url":"articles/glossary-body/","image":"articles/media/glossary/terms/body/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/body"},{"title":"Bold","slug":"glossary-bold","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A common weight of a typeface—one that’s heavier than a Regular, but not as heavy as an Extra Bold or Black.","url":"articles/glossary-bold/","image":"articles/media/glossary/terms/bold/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/bold"},{"title":"Calligraphy","slug":"glossary-calligraphy","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The practice of writing with a deliberate and artful style, with a consistency across letterforms.","url":"articles/glossary-calligraphy/","image":"articles/media/glossary/terms/calligraphy/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/calligraphy"},{"title":"Cap height","slug":"glossary-cap-height","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The height of a typeface’s uppercase letters, measured from the baseline to the top of the glyph. This is usually slightly lower than the ascender height.","url":"articles/glossary-cap-height/","image":"articles/media/glossary/terms/cap_height/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/cap_height"},{"title":"Casual axis (CASL)","slug":"glossary-casual-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts. Along this axis, letterforms adjust from a more serious style to a more casual style.","url":"articles/glossary-casual-axis/","image":"articles/media/glossary/terms/casual_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/casual_axis"},{"title":"Character","slug":"glossary-character","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A single unit of language, such as a letter or mark. Closely related to—but not the same as—a glyph.","url":"articles/glossary-character/","image":"articles/media/glossary/terms/character/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/character"},{"title":"CJK","slug":"glossary-cjk","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The shorthand collective name for the Chinese, Japanese, and Korean writing systems.","url":"articles/glossary-cjk/","image":"articles/media/glossary/terms/cjk/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/cjk"},{"title":"Classification","slug":"glossary-classification","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The act of dividing up different styles of type design, usually by genre or historical period, for more meaningful description and/or browsing.","url":"articles/glossary-classification/","image":"articles/media/glossary/terms/classification/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/classification"},{"title":"Color","slug":"glossary-color","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The overall presence of type on a page—its lightness and darkness compared to the negative space.","url":"articles/glossary-color/","image":"articles/media/glossary/terms/color/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/color"},{"title":"Color fonts","slug":"glossary-color-fonts","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A font that can use multiple colors in a single glyph, rather than a flat single color used by non-color (monochromatic) fonts.","url":"articles/glossary-color-fonts/","image":"articles/media/glossary/terms/color_fonts/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/color_fonts"},{"title":"Condensed, narrow, or compressed","slug":"glossary-condensed-narrow-compressed","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A reference to a typeface’s width, usually implying a narrower version of its normal width.","url":"articles/glossary-condensed-narrow-compressed/","image":"articles/media/glossary/terms/condensed_narrow_compressed/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/condensed_narrow_compressed"},{"title":"Contrast","slug":"glossary-contrast","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The difference between the thick and thin parts of a stroke. A monolinear typeface has low stroke contrast, and is the opposite of a high contrast face.","url":"articles/glossary-contrast/","image":"articles/media/glossary/terms/contrast/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/contrast"},{"title":"Contrast axis (CTRS)","slug":"glossary-contrast-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis in some variable fonts that controls the difference between thick and thin strokes, from no contrast to extreme or reversed contrast.","url":"articles/glossary-contrast-axis/","image":"articles/media/glossary/terms/contrast_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/contrast_axis"},{"title":"Counter","slug":"glossary-counter","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The transparent space enclosed inside a letterform. Counters can be closed, as in “o” and “d”, or open, as in “c” and “u.”","url":"articles/glossary-counter/","image":"articles/media/glossary/terms/counter/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/counter"},{"title":"Cursive axis (CRSV)","slug":"glossary-cursive-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that controls the substitution of cursive forms.","url":"articles/glossary-cursive-axis/","image":"articles/media/glossary/terms/cursive_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/cursive_axis"},{"title":"Cyrillic","slug":"glossary-cyrillic","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The writing system used for Russian and various other languages across Eurasia and beyond.","url":"articles/glossary-cyrillic/","image":"articles/media/glossary/terms/cyrillic/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/cyrillic"},{"title":"Dashes","slug":"glossary-dashes","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A group of characters that take the form of horizontal bars, differentiated by the width of the bar.","url":"articles/glossary-dashes/","image":"articles/media/glossary/terms/dashes/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/dashes"},{"title":"Designspace","slug":"glossary-designspace","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A system specified during the type design process that controls how a variable font’s appearance changes, via interpolation from the master designs.","url":"articles/glossary-designspace/","image":"articles/media/glossary/terms/designspace/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/designspace"},{"title":"Diacritics, or accent marks","slug":"glossary-diacritic-accent-marks","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Small marks that appear above or below glyphs, usually to offer hints at pronunciation.","url":"articles/glossary-diacritic-accent-marks/","image":"articles/media/glossary/terms/diacritic_accent_marks/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/diacritic_accent_marks"},{"title":"Dingbat","slug":"glossary-dingbat","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A glyph that is not a letter, number, or form of punctuation. Most dingbats are pictograms.","url":"articles/glossary-dingbat/","image":"articles/media/glossary/terms/dingbat/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/dingbat"},{"title":"Display","slug":"glossary-display","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"When referring to optical sizing, “display” is a counterpart to “body,” representing stylistic differences that make the variant more suitable to being set at large sizes.","url":"articles/glossary-display/","image":"articles/media/glossary/terms/display/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/display"},{"title":"Drop cap","slug":"glossary-drop-cap","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A large, uppercase letter used for decoration in the opening of a piece (or section) of text, most often employed in editorial scenarios.","url":"articles/glossary-drop-cap/","image":"articles/media/glossary/terms/drop_cap/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/drop_cap"},{"title":"Extrusion Depth axis (EDPT)","slug":"glossary-edpt-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to control the depth of three-dimensional letterforms.","url":"articles/glossary-edpt-axis/","image":"articles/media/glossary/terms/edpt_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/edpt_axis"},{"title":"Edge Highlight axis (EHLT)","slug":"glossary-ehlt-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to control the thickness of the highlighted part of edges in three-dimensional letterforms.","url":"articles/glossary-ehlt-axis/","image":"articles/media/glossary/terms/ehlt_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/ehlt_axis"},{"title":"Element Grid axis (ELGR)","slug":"glossary-elgr-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some modular variable fonts where letterforms are composed using multiple copies of the same element.","url":"articles/glossary-elgr-axis/","image":"articles/media/glossary/terms/elgr_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/elgr_axis"},{"title":"Element Shape axis (ELSH)","slug":"glossary-elsh-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some modular variable fonts where letterforms are composed using multiple copies of the same element.","url":"articles/glossary-elsh-axis/","image":"articles/media/glossary/terms/elsh_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/elsh_axis"},{"title":"Element Expansion axis (ELXP)","slug":"glossary-elxp-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some modular variable fonts where letterforms are composed using multiple copies of the same element.","url":"articles/glossary-elxp-axis/","image":"articles/media/glossary/terms/elxp_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/elxp_axis"},{"title":"Em","slug":"glossary-em","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A unit of measurement, 1em is equal to the size of a font. Adjusting font size will resize glyphs relative to the em square.","url":"articles/glossary-em/","image":"articles/media/glossary/terms/em/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/em"},{"title":"Emoji","slug":"glossary-emoji","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A pictogram intended to convey emotional meaning, usually used as a supplement to text in order to clarify intent.","url":"articles/glossary-emoji/","image":"articles/media/glossary/terms/emoji/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/emoji"},{"title":"En","slug":"glossary-en","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A unit of measurement based on half the width of the capital M in a particular typeface. The en dash takes up approximately half the width of an em.","url":"articles/glossary-en/","image":"articles/media/glossary/terms/en/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/en"},{"title":"Enlarge axis (ENLA)","slug":"glossary-enla-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to scale certain lowercase letters up to a size between ordinary lowercase and full capitals, based on the enlarged minuscules of medieval manuscripts.","url":"articles/glossary-enla-axis/","image":"articles/media/glossary/terms/enla_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/enla_axis"},{"title":"Family, type family, or font family","slug":"glossary-family-or-type-family-or-font-family","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A collection of variations on a typeface design. Each instance (usually a weight or style) forms part of the family.","url":"articles/glossary-family-or-type-family-or-font-family/","image":"articles/media/glossary/terms/family_or_type_family_or_font_family/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/family_or_type_family_or_font_family"},{"title":"Faux, fake, pseudo, or synthesized","slug":"glossary-faux-fake-pseudo-synthesized","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The attempt by software to emulate an italic style, bold (or other) weight, or small caps in lieu of actual font files for those variants.","url":"articles/glossary-faux-fake-pseudo-synthesized/","image":"articles/media/glossary/terms/faux_fake_pseudo_synthesized/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/faux_fake_pseudo_synthesized"},{"title":"File size","slug":"glossary-file-size","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A key consideration for web typography: Font files, like all website assets, are resources that need downloading—this affects overall loading times.","url":"articles/glossary-file-size/","image":"articles/media/glossary/terms/file_size/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/file_size"},{"title":"Fill axis (FILL)","slug":"glossary-fill-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts, intended to provide a treatment of the design that fills in transparent forms with opaque ones.","url":"articles/glossary-fill-axis/","image":"articles/media/glossary/terms/fill_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/fill_axis"},{"title":"Flare axis (FLAR)","slug":"glossary-flar-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to control how the strokes modulate from their upright parts to their flared extremes.","url":"articles/glossary-flar-axis/","image":"articles/media/glossary/terms/flar_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/flar_axis"},{"title":"FOIT","slug":"glossary-foit","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An acronym for “flash of invisible text”—a phenomenon experienced when a web page loads without text before rendering the intended font(s).","url":"articles/glossary-foit/","image":"articles/media/glossary/terms/foit/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/foit"},{"title":"Font","slug":"glossary-font","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A typeface is what you see; a font is what you use.","url":"articles/glossary-font/","image":"articles/media/glossary/terms/font/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/font"},{"title":"Font format","slug":"glossary-font-format","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The specific file type(s) designated for font data, with a font itself being the manifestation of a typeface.","url":"articles/glossary-font-format/","image":"articles/media/glossary/terms/font_format/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/font_format"},{"title":"Font picker","slug":"glossary-font-picker","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The part of a user interface that specifically allows the user to choose a font.","url":"articles/glossary-font-picker/","image":"articles/media/glossary/terms/font_picker/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/font_picker"},{"title":"FOUT","slug":"glossary-fout","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An acronym for “flash of unstyled text”—a phenomenon experienced when a web page loads with the type set using system fonts before switching to the intended typeface(s).","url":"articles/glossary-fout/","image":"articles/media/glossary/terms/fout/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/fout"},{"title":"Fractions","slug":"glossary-fractions","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The group of glyphs in any given typeface that's dedicated to the optimal rendering of mathematical fractions.","url":"articles/glossary-fractions/","image":"articles/media/glossary/terms/fractions/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/fractions"},{"title":"Guides Opacity axis (GDOP)","slug":"glossary-gdop-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to adjust the visibility of handwriting guides built into the glyphs, from fully visible to fully invisible.","url":"articles/glossary-gdop-axis/","image":"articles/media/glossary/terms/gdop_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/gdop_axis"},{"title":"Geometric Form axis (GEOM)","slug":"glossary-geom-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to transform letterforms from their default construction into simplified geometric shapes.","url":"articles/glossary-geom-axis/","image":"articles/media/glossary/terms/geom_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/geom_axis"},{"title":"Geometric","slug":"glossary-geometric","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A genre classification of typefaces—almost always sans serifs—so called because of their geometric construction.","url":"articles/glossary-geometric/","image":"articles/media/glossary/terms/geometric/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/geometric"},{"title":"Glyph","slug":"glossary-glyph","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A single representation of a character, taking up one space in a font’s glyph table. A character can have multiple glyphs.","url":"articles/glossary-glyph/","image":"articles/media/glossary/terms/glyph/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/glyph"},{"title":"Grade","slug":"glossary-grade","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An attempt to keep type appearing consistent across different media, or in certain contexts.","url":"articles/glossary-grade/","image":"articles/media/glossary/terms/grade/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/grade"},{"title":"Grade axis (GRAD)","slug":"glossary-grade-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts. Changing grade allows us to finesse the style from lighter to heavier in typographic color.","url":"articles/glossary-grade-axis/","image":"articles/media/glossary/terms/grade_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/grade_axis"},{"title":"Greek script","slug":"glossary-greek-script","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The writing system used for the Greek language, not be confused with the erroneously used “Greek” placeholder text.","url":"articles/glossary-greek-script/","image":"articles/media/glossary/terms/greek_script/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/greek_script"},{"title":"Grotesque & Neo-grotesque","slug":"glossary-grotesque-neo-grotesque","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The first form of sans serif type (which appeared in the early 19th century [Grotesque]) and the subsequent evolution of this style (Neo-grotesque).","url":"articles/glossary-grotesque-neo-grotesque/","image":"articles/media/glossary/terms/grotesque_neo_grotesque/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/grotesque_neo_grotesque"},{"title":"Handwriting","slug":"glossary-handwriting","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The act of writing by the human hand, usually with a pen or pencil, in a casual manner; or: a genre classification of type.","url":"articles/glossary-handwriting/","image":"articles/media/glossary/terms/handwriting/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/handwriting"},{"title":"Hanging punctuation","slug":"glossary-hanging-punctuation","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Punctuation marks that appear outside of a text frame (usually to the left in left-aligned, left-to-right text) to create a more pleasing vertical rhythm.","url":"articles/glossary-hanging-punctuation/","image":"articles/media/glossary/terms/hanging_punctuation/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/hanging_punctuation"},{"title":"Hyper Expansion axis (HEXP)","slug":"glossary-hexp-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to stretch the distance among glyphs by increasing the width of the glyphs themselves and also their connections or the spacing.","url":"articles/glossary-hexp-axis/","image":"articles/media/glossary/terms/hexp_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/hexp_axis"},{"title":"Hierarchy","slug":"glossary-hierarchy","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The overall structure of a document and the relationship between elements within the text.","url":"articles/glossary-hierarchy/","image":"articles/media/glossary/terms/hierarchy/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/hierarchy"},{"title":"Hinting","slug":"glossary-hinting","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The process of including programmatic “hints” in a font file to help text rendering software accurately recreate a typeface’s design at a low resolution.","url":"articles/glossary-hinting/","image":"articles/media/glossary/terms/hinting/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/hinting"},{"title":"Homoglyph","slug":"glossary-homoglyph","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A glyph with a design that can appear indistinguishable from—or least very similar to—another glyph with a separate meaning.","url":"articles/glossary-homoglyph/","image":"articles/media/glossary/terms/homoglyph/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/homoglyph"},{"title":"Humanist, or Old Style","slug":"glossary-humanist-old-style","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A historical classification for typefaces that draws inspiration from Roman lettering and calligraphy to include forms that reference the stroke of a pen.","url":"articles/glossary-humanist-old-style/","image":"articles/media/glossary/terms/humanist_old_style/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/humanist_old_style"},{"title":"Hyphenation","slug":"glossary-hyphenation","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The act of using the hyphen character to either break single words over two lines, or join multiple words.","url":"articles/glossary-hyphenation/","image":"articles/media/glossary/terms/hyphenation/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/hyphenation"},{"title":"Icon font","slug":"glossary-icon-font","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A font that exclusively contains icon glyphs rather than alphanumeric glyphs.","url":"articles/glossary-icon-font/","image":"articles/media/glossary/terms/icon_font/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/icon_font"},{"title":"Icon & symbol","slug":"glossary-icon-symbol","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An icon is a literal, visual representation of the thing it represents, whereas a symbol can be a more abstract representation of something.","url":"articles/glossary-icon-symbol/","image":"articles/media/glossary/terms/icon_symbol/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/icon_symbol"},{"title":"Axis: Informality axis (INFM)","slug":"glossary-infm-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to introduce irregular shaping or adjusted proportions to mimic natural handwriting.","url":"articles/glossary-infm-axis/","image":"articles/media/glossary/terms/infm_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/infm_axis"},{"title":"Ink trap","slug":"glossary-ink-trap","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An intentional negative space built into letterforms to literally trap ink at certain intersections of the strokes.","url":"articles/glossary-ink-trap/","image":"articles/media/glossary/terms/ink_trap/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/ink_trap"},{"title":"Instance","slug":"glossary-instance","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An instance of a variable font is equivalent to a font in a font family.","url":"articles/glossary-instance/","image":"articles/media/glossary/terms/instance/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/instance"},{"title":"Interpolation","slug":"glossary-interpolation","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The use of software to populate intermediate instances of a font between two masters.","url":"articles/glossary-interpolation/","image":"articles/media/glossary/terms/interpolation/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/interpolation"},{"title":"Italic","slug":"glossary-italic","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An almost-always slanted type style that's designed to create emphasis in text. Originally based on semi-cursive forms, italics are a direct contrast to the Roman style.","url":"articles/glossary-italic/","image":"articles/media/glossary/terms/italic/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/italic"},{"title":"Italic axis (ital)","slug":"glossary-italic-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that turns the font file’s italic parameter on or off.","url":"articles/glossary-italic-axis/","image":"articles/media/glossary/terms/italic_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/italic_axis"},{"title":"Jitter axis (JITT)","slug":"glossary-jitt-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to apply irregular displacement to glyphs, emulating the mechanical imperfections of vintage printing equipment.","url":"articles/glossary-jitt-axis/","image":"articles/media/glossary/terms/jitt_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/jitt_axis"},{"title":"Kerning & kerning pairs","slug":"glossary-kerning-kerning-pairs","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Kerning is the adjustment of spacing between two specific glyphs; kerning pairs are the type designer's embedded kerning instructions within a font file.","url":"articles/glossary-kerning-kerning-pairs/","image":"articles/media/glossary/terms/kerning_kerning_pairs/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/kerning_kerning_pairs"},{"title":"Latin","slug":"glossary-latin","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"In typography, “Latin script” refers to the most widely adopted writing system in the world.","url":"articles/glossary-latin/","image":"articles/media/glossary/terms/latin/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/latin"},{"title":"Legibility","slug":"glossary-legibility","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Describes how a typeface’s glyphs can be correctly identified as characters and words, including how individual characters can be distinguished from one another.","url":"articles/glossary-legibility/","image":"articles/media/glossary/terms/legibility/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/legibility"},{"title":"Letterform","slug":"glossary-letterform","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The unique shape of a letter, with characteristics shared throughout a typeface.","url":"articles/glossary-letterform/","image":"articles/media/glossary/terms/letterform/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/letterform"},{"title":"Lettering","slug":"glossary-lettering","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The art of drawing letters rather than writing them, distinct from handwriting, calligraphy, and typography.","url":"articles/glossary-lettering/","image":"articles/media/glossary/terms/lettering/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/lettering"},{"title":"Letters","slug":"glossary-letters","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The set of graphical symbols used to represent speech sounds in an alphabetic writing system.","url":"articles/glossary-letters/","image":"articles/media/glossary/terms/letters/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/letters"},{"title":"Licensing","slug":"glossary-licensing","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"In typography, the process of obtaining a font license by a user. A license is a legal statement made by the type foundry about what users can and can’t do with the fonts. Even fonts obtained for free are licensed.","url":"articles/glossary-licensing/","image":"articles/media/glossary/terms/licensing/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/licensing"},{"title":"Ligature","slug":"glossary-ligature","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A glyph that combines the shapes of two (or more) characters into a new form, making for a more harmonious reading experience.","url":"articles/glossary-ligature/","image":"articles/media/glossary/terms/ligature/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/ligature"},{"title":"Line height & leading","slug":"glossary-line-height-leading","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The vertical space between two lines of type, measured from the baseline of one line of type to the baseline of the next.","url":"articles/glossary-line-height-leading/","image":"articles/media/glossary/terms/line_height_leading/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/line_height_leading"},{"title":"Lockup","slug":"glossary-lockup","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The fixed arrangement of two or more individual elements (e.g. a logomark together with a logotype).","url":"articles/glossary-lockup/","image":"articles/media/glossary/terms/lockup/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/lockup"},{"title":"Logo, logomark, logotype","slug":"glossary-logo-logomark-logotype","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A logo is a unique combination of elements—usually graphics and type—that creates a reproducible and recognizable design.","url":"articles/glossary-logo-logomark-logotype/","image":"articles/media/glossary/terms/logo_logomark_logotype/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/logo_logomark_logotype"},{"title":"Masters","slug":"glossary-masters","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A complete set of glyphs designed in one particular style within a type family, used to create intermediate weights.","url":"articles/glossary-masters/","image":"articles/media/glossary/terms/masters/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/masters"},{"title":"Material Symbols","slug":"glossary-material-symbols","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The variable version of the Material Icons font, combining over 2,000 glyphs into a single font file with a wide range of design variants.","url":"articles/glossary-material-symbols/","image":"articles/media/glossary/terms/material_symbols/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/material_symbols"},{"title":"Measure, or line length","slug":"glossary-measure-line-length","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The length of a line of text. In paragraph text, this is therefore also the assumed width of the whole text block.","url":"articles/glossary-measure-line-length/","image":"articles/media/glossary/terms/measure_line_length/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/measure_line_length"},{"title":"Monolinear","slug":"glossary-monolinear","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A typeface with strokes of a consistent thickness; i.e., little or no contrast. Typically, sans serifs tend to have less contrast than serifs.","url":"articles/glossary-monolinear/","image":"articles/media/glossary/terms/monolinear/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/monolinear"},{"title":"Monospace axis (MONO)","slug":"glossary-monospace-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that adjusts the glyphs from a proportional width to a fixed width.","url":"articles/glossary-monospace-axis/","image":"articles/media/glossary/terms/monospace_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/monospace_axis"},{"title":"Monospaced","slug":"glossary-monospaced","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A grouping of typefaces in which all or most characters take up the same amount of horizontal space.","url":"articles/glossary-monospaced/","image":"articles/media/glossary/terms/monospaced/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/monospaced"},{"title":"Morph axis (MORF)","slug":"glossary-morf-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to unconventionally change the shape, size, and position of elements that make up a letterform.","url":"articles/glossary-morf-axis/","image":"articles/media/glossary/terms/morf_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/morf_axis"},{"title":"Multiplexed, duplexed, or uniwidth","slug":"glossary-multiplexed-duplexed-uniwidth","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A typeface in which each of its weights takes up exactly the same horizontal space.","url":"articles/glossary-multiplexed-duplexed-uniwidth/","image":"articles/media/glossary/terms/multiplexed_duplexed_uniwidth/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/multiplexed_duplexed_uniwidth"},{"title":"Numerals, or figures","slug":"glossary-numerals-figures","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The glyphs in a typeface that represent numbers. In OpenType, it’s possible to select different kinds of numerals intended for different uses.","url":"articles/glossary-numerals-figures/","image":"articles/media/glossary/terms/numerals_figures/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/numerals_figures"},{"title":"Oblique","slug":"glossary-oblique","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Slanted versions of their Roman counterparts. They are not the same as italics, which are original drawings.","url":"articles/glossary-oblique/","image":"articles/media/glossary/terms/oblique/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/oblique"},{"title":"OpenType","slug":"glossary-open-type","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A font technology and associated font format, developed by Microsoft and Adobe, which allows the end user to access additional features in a font.","url":"articles/glossary-open-type/","image":"articles/media/glossary/terms/open_type/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/open_type"},{"title":"Optical Size axis (opsz)","slug":"glossary-optical-size-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that controls the font file’s optical size optimizations.","url":"articles/glossary-optical-size-axis/","image":"articles/media/glossary/terms/optical_size_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/optical_size_axis"},{"title":"Optical sizes","slug":"glossary-optical-sizes","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Different versions of a typeface optimized for use at specific sizes or size ranges.","url":"articles/glossary-optical-sizes/","image":"articles/media/glossary/terms/optical_sizes/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/optical_sizes"},{"title":"Ordinals","slug":"glossary-ordinals","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The small letters that appear next to a numeral. In English, examples include the “st” in “1st”, or “nd” in “2nd”.","url":"articles/glossary-ordinals/","image":"articles/media/glossary/terms/ordinals/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/ordinals"},{"title":"Overshoot","slug":"glossary-overshoot","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The part of a letterform that extends above or below the vertical dimensions of flatter glyphs.","url":"articles/glossary-overshoot/","image":"articles/media/glossary/terms/overshoot/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/overshoot"},{"title":"Parametric axis","slug":"glossary-parametric-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A high-precision tool, intended only for expert use, that enables finessing of strokes, counters and vertical alignments. Parametric axes can be used to address many typographic challenges.","url":"articles/glossary-parametric-axis/","image":"articles/media/glossary/terms/parametric_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/parametric_axis"},{"title":"Parametric font","slug":"glossary-parametric-font","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A variable font where one or more of its axes are parametric axes.","url":"articles/glossary-parametric-font/","image":"articles/media/glossary/terms/parametric_font/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/parametric_font"},{"title":"Placeholder text","slug":"glossary-placeholder-text","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Text that is set temporarily in place of actual copy, intended to not be read.","url":"articles/glossary-placeholder-text/","image":"articles/media/glossary/terms/placeholder_text/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/placeholder_text"},{"title":"Point size","slug":"glossary-point-size","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A unit of measurement for type, employed for hundreds of years. In print design, points remain the standard unit of measuring font size.","url":"articles/glossary-point-size/","image":"articles/media/glossary/terms/point_size/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/point_size"},{"title":"Quotation mark","slug":"glossary-quotation-mark","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A form of punctuation with double and single variations, used to open and close a quotation accordingly.","url":"articles/glossary-quotation-mark/","image":"articles/media/glossary/terms/quotation_mark/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/quotation_mark"},{"title":"Rag","slug":"glossary-rag","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The irregular edge of an unjustified text block.","url":"articles/glossary-rag/","image":"articles/media/glossary/terms/rag/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/rag"},{"title":"Readability","slug":"glossary-readability","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Describes how comfortable it is for a person to engage with text created with legible type.","url":"articles/glossary-readability/","image":"articles/media/glossary/terms/readability/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/readability"},{"title":"Reflow","slug":"glossary-reflow","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The act of words, or parts of words, moving from one line of type to the line above or below because of a typographic change.","url":"articles/glossary-reflow/","image":"articles/media/glossary/terms/reflow/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/reflow"},{"title":"Regular, or upright","slug":"glossary-regular-upright","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Either the “Regular” weight of a typeface, usually assigned the font-weight value of 400, or the “Regular” upright style (i.e., non-italic) of a typeface.","url":"articles/glossary-regular-upright/","image":"articles/media/glossary/terms/regular_upright/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/regular_upright"},{"title":"Reversed-out","slug":"glossary-reversed-out","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The scenario of setting white or light-colored type on top of a black or dark-colored background.","url":"articles/glossary-reversed-out/","image":"articles/media/glossary/terms/reversed_out/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/reversed_out"},{"title":"Rhythm","slug":"glossary-rhythm","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The perceived movement that flows through text, whether that’s through the letterforms of one word, or through a whole block of text.","url":"articles/glossary-rhythm/","image":"articles/media/glossary/terms/rhythm/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/rhythm"},{"title":"Roundness axis (ROND)","slug":"glossary-rond-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to change shapes from sharp and angular defaults to rounded versions.","url":"articles/glossary-rond-axis/","image":"articles/media/glossary/terms/rond_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/rond_axis"},{"title":"Sans serif","slug":"glossary-sans-serif","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A typeface designed without serifs. Typically, sans serif faces have lower contrast and larger x-heights than serifs.","url":"articles/glossary-sans-serif/","image":"articles/media/glossary/terms/sans_serif/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/sans_serif"},{"title":"Scale","slug":"glossary-scale","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A pre-defined set of intervals that dictate font sizes within a typographic system.","url":"articles/glossary-scale/","image":"articles/media/glossary/terms/scale/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/scale"},{"title":"Scanlines axis (SCAN)","slug":"glossary-scan-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that control the thickness of the scanlines that make up the glyph shapes.","url":"articles/glossary-scan-axis/","image":"articles/media/glossary/terms/scan_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/scan_axis"},{"title":"Script","slug":"glossary-script","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A visual representation of verbal speech, which, when combined with usage conventions, constitutes a writing system.","url":"articles/glossary-script/","image":"articles/media/glossary/terms/script/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/script"},{"title":"Script (typeface style)","slug":"glossary-script-typeface-style","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A genre classification for decorative typefaces that take direct influence from hand lettering, and are usually intended for display purposes.","url":"articles/glossary-script-typeface-style/","image":"articles/media/glossary/terms/script_typeface_style/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/script_typeface_style"},{"title":"Serif","slug":"glossary-serif","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Either the mark or line that can sometimes appear at the end of a character’s stroke, or the collective name for typefaces that use serifs in their design.","url":"articles/glossary-serif/","image":"articles/media/glossary/terms/serif/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/serif"},{"title":"Shadow Length (SHLN)","slug":"glossary-shadowlength-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that controls the length of the font’s shadow, from no visible shadow to the maximum shadow effect defined by the type designer.","url":"articles/glossary-shadowlength-axis/","image":"articles/media/glossary/terms/shadowlength_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/shadowlength_axis"},{"title":"Shaping","slug":"glossary-shaping","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The automatic process of combining plain text with a font, according to rules supplied by the shaping engine and the font itself.","url":"articles/glossary-shaping/","image":"articles/media/glossary/terms/shaping/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/shaping"},{"title":"Sharpness axis (SHRP)","slug":"glossary-shrp-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to adjust the shape of the letterforms’ terminals.","url":"articles/glossary-shrp-axis/","image":"articles/media/glossary/terms/shrp_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/shrp_axis"},{"title":"Slab serif, Egyptian, or Clarendon","slug":"glossary-slab-serif-egyptian-clarendon","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A group of typefaces close to sans serifs in their construction—including their generally low contrast—but possessing serifs that match the overall stroke.","url":"articles/glossary-slab-serif-egyptian-clarendon/","image":"articles/media/glossary/terms/slab_serif_egyptian_clarendon/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/slab_serif_egyptian_clarendon"},{"title":"Slant axis (slnt)","slug":"glossary-slant-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that controls the font file’s slant parameter for oblique styles.","url":"articles/glossary-slant-axis/","image":"articles/media/glossary/terms/slant_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/slant_axis"},{"title":"Small caps","slug":"glossary-small-caps","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Small-scale, uppercase letterforms designed to sit alongside lowercase type.","url":"articles/glossary-small-caps/","image":"articles/media/glossary/terms/small_caps/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/small_caps"},{"title":"Softness axis (SOFT)","slug":"glossary-softness-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts. At the end of this axis, letterforms become more soft and rounded.","url":"articles/glossary-softness-axis/","image":"articles/media/glossary/terms/softness_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/softness_axis"},{"title":"Spacing axis (SPAC)","slug":"glossary-spac-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to adjust the spacing among characters overall, as a percentage from the default spacing.","url":"articles/glossary-spac-axis/","image":"articles/media/glossary/terms/spac_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/spac_axis"},{"title":"Spaces","slug":"glossary-spaces","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Glyphs that contain no visible strokes but still have specific values for width, and occupy a unique unicode cell in the glyph table.","url":"articles/glossary-spaces/","image":"articles/media/glossary/terms/spaces/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/spaces"},{"title":"Spacing","slug":"glossary-spacing","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"In type design, the act of setting the horizontal space around each glyph.","url":"articles/glossary-spacing/","image":"articles/media/glossary/terms/spacing/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/spacing"},{"title":"Stroke","slug":"glossary-stroke","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The main line that makes up the appearance of a character. The term is derived from the penmanship inherent in hand-lettering.","url":"articles/glossary-stroke/","image":"articles/media/glossary/terms/stroke/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/stroke"},{"title":"Style","slug":"glossary-style","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Regular, italic, oblique, and small caps are all examples of styles that can exist within a single typeface. See also: Stylistic sets.","url":"articles/glossary-style/","image":"articles/media/glossary/terms/style/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/style"},{"title":"Stylistic sets","slug":"glossary-stylistic-sets","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Groupings of alternate glyphs that allow the user to switch on (via OpenType) sets of related alternate glyphs one at a time.","url":"articles/glossary-stylistic-sets/","image":"articles/media/glossary/terms/stylistic_sets/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/stylistic_sets"},{"title":"Subsetting","slug":"glossary-subsetting","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The practice of creating a “subset” of a font—a file that contains a custom (and usually limited) collection of glyphs.","url":"articles/glossary-subsetting/","image":"articles/media/glossary/terms/subsetting/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/subsetting"},{"title":"Superfamily","slug":"glossary-superfamily","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The collective grouping of several explicitly related type families—such as a serif, sans, and slab—that all share the same underlying structure to their design.","url":"articles/glossary-superfamily/","image":"articles/media/glossary/terms/superfamily/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/superfamily"},{"title":"Superscript & subscript","slug":"glossary-superscript-subscript","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Text formatted to appear smaller than the surrounding text, usually aligned slightly above the top (super) or bottom (sub) of regular type.","url":"articles/glossary-superscript-subscript/","image":"articles/media/glossary/terms/superscript_subscript/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/superscript_subscript"},{"title":"Swash glyph","slug":"glossary-swash-glyph","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A decorative variant of a glyph, most commonly found in serif typefaces, which has more elaborate and ornate flourishes than its regular version.","url":"articles/glossary-swash-glyph/","image":"articles/media/glossary/terms/swash_glyph/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/swash_glyph"},{"title":"System font, or web-safe font","slug":"glossary-system-font-web-safe-font","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A font already assumed to be on the vast majority of users’ devices, with no need for a web font to be downloaded.","url":"articles/glossary-system-font-web-safe-font/","image":"articles/media/glossary/terms/system_font_web_safe_font/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/system_font_web_safe_font"},{"title":"Terminal","slug":"glossary-terminal","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The ending of the stroke in a typeface design, which may or may not be a serif.","url":"articles/glossary-terminal/","image":"articles/media/glossary/terms/terminal/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/terminal"},{"title":"Text, or copy","slug":"glossary-text-copy","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The content itself—the thing we set in type. However, the word “text” can also imply the text size, which is then interchangeable with the term “body”.","url":"articles/glossary-text-copy/","image":"articles/media/glossary/terms/text_copy/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/text_copy"},{"title":"Tofu","slug":"glossary-tofu","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A symbol that has come to be known as “tofu”, displayed when a character is not present in a font and no fallback option is available.","url":"articles/glossary-tofu/","image":"articles/media/glossary/terms/tofu/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/tofu"},{"title":"Tracking, or letter-spacing","slug":"glossary-tracking-letter-spacing","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The spacing between glyphs applied to an entire piece of text. In CSS, this is called letter-spacing. ","url":"articles/glossary-tracking-letter-spacing/","image":"articles/media/glossary/terms/tracking_letter_spacing/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/tracking_letter_spacing"},{"title":"Transitional, or Neo-classical","slug":"glossary-transitional-neo-classical","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A historical classification for typefaces that reference elements of human penmanship, but do so in a more ordered and structured form.","url":"articles/glossary-transitional-neo-classical/","image":"articles/media/glossary/terms/transitional_neo_classical/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/transitional_neo_classical"},{"title":"Type","slug":"glossary-type","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The mechanized and consistent reproduction of letterforms that make up written language.","url":"articles/glossary-type/","image":"articles/media/glossary/terms/type/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/type"},{"title":"Type designer","slug":"glossary-type-designer","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Someone who designs typefaces. Not to be confused with a typographer (someone who designs with typefaces).","url":"articles/glossary-type-designer/","image":"articles/media/glossary/terms/type_designer/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/type_designer"},{"title":"Type foundry","slug":"glossary-type-foundry","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An organization that publishes typefaces and releases fonts. Foundries are almost always formed by a type designer.","url":"articles/glossary-type-foundry/","image":"articles/media/glossary/terms/type_foundry/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/type_foundry"},{"title":"Typeface","slug":"glossary-typeface","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A typeface is what you see; a font is what you use.","url":"articles/glossary-typeface/","image":"articles/media/glossary/terms/typeface/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/typeface"},{"title":"Typesetting","slug":"glossary-typesetting","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Typesetting is the act of setting type: arranging characters and making informed typographic decisions that will optimize the readability of that text.","url":"articles/glossary-typesetting/","image":"articles/media/glossary/terms/typesetting/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/typesetting"},{"title":"Typographer","slug":"glossary-typographer","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Someone who designs with type and practices typography. Not to be confused with a type designer (someone who designs typefaces).","url":"articles/glossary-typographer/","image":"articles/media/glossary/terms/typographer/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/typographer"},{"title":"Typography","slug":"glossary-typography","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The practice of making informed decisions about the setting of type. Not to be confused with type design.","url":"articles/glossary-typography/","image":"articles/media/glossary/terms/typography/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/typography"},{"title":"Unicode","slug":"glossary-unicode","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Every single glyph in a font has an associated unicode reference: a unique identifier that corresponds with the same character in other typefaces.","url":"articles/glossary-unicode/","image":"articles/media/glossary/terms/unicode/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/unicode"},{"title":"Unit","slug":"glossary-unit","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A way of measuring font size, line height, line-length, margins, etc. Points, pixels, and ems (or rems) are the units most relevant to today’s typesetting needs.","url":"articles/glossary-unit/","image":"articles/media/glossary/terms/unit/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/unit"},{"title":"Uppercase & lowercase","slug":"glossary-uppercase-lowercase","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Uppercase (or capital) letters are used for the beginning of sentences, proper nouns, and abbreviations. Lowercase letters are used for every other scenario.","url":"articles/glossary-uppercase-lowercase/","image":"articles/media/glossary/terms/uppercase_lowercase/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/uppercase_lowercase"},{"title":"Variable Fonts","slug":"glossary-variable-fonts","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A relatively new format that allows one font to contain multiple variations, which can then be manipulated by the end user.","url":"articles/glossary-variable-fonts/","image":"articles/media/glossary/terms/variable_fonts/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/variable_fonts"},{"title":"Viewport","slug":"glossary-viewport","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The size of the browser window, or any area that a website or app uses as its display surface, not including any “chrome”.","url":"articles/glossary-viewport/","image":"articles/media/glossary/terms/viewport/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/viewport"},{"title":"Volume axis (VOLM)","slug":"glossary-volm-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to exaggerate details of a typeface in order to emphasize its personality.","url":"articles/glossary-volm-axis/","image":"articles/media/glossary/terms/volm_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/volm_axis"},{"title":"Web font","slug":"glossary-web-font","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Any font that’s used in a website’s design that isn’t installed by default on the end user’s device—a counterpart to a “system font.","url":"articles/glossary-web-font/","image":"articles/media/glossary/terms/web_font/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/web_font"},{"title":"Weight","slug":"glossary-weight","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The overall thickness of a font’s stroke. The most common weights are regular and bold, but can cover extremes from the very light to the very heavy.","url":"articles/glossary-weight/","image":"articles/media/glossary/terms/weight/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/weight"},{"title":"Weight axis (wght)","slug":"glossary-weight-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that controls the font file’s weight parameter.","url":"articles/glossary-weight-axis/","image":"articles/media/glossary/terms/weight_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/weight_axis"},{"title":"Wide, or extended","slug":"glossary-wide-extended","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Typefaces with characters that typically take up a great deal of horizontal space, sitting at the opposite end of “condensed” or “compressed” type.","url":"articles/glossary-wide-extended/","image":"articles/media/glossary/terms/wide_extended/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/wide_extended"},{"title":"Widows & orphans","slug":"glossary-widows-orphans","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"Lines that appear by themselves at either the top (widow) or bottom (orphan) of a column of text.","url":"articles/glossary-widows-orphans/","image":"articles/media/glossary/terms/widows_orphans/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/widows_orphans"},{"title":"Width","slug":"glossary-width","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The amount of horizontal space taken up by a typeface’s characters. A condensed face takes up considerably less space than a wide face.","url":"articles/glossary-width/","image":"articles/media/glossary/terms/width/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/width"},{"title":"Width axis (wdth)","slug":"glossary-width-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that controls the font file’s width parameter.","url":"articles/glossary-width-axis/","image":"articles/media/glossary/terms/width_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/width_axis"},{"title":"Wonky axis (WONK)","slug":"glossary-wonky-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that controls the substitution of “wonky” forms.","url":"articles/glossary-wonky-axis/","image":"articles/media/glossary/terms/wonky_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/wonky_axis"},{"title":"Writing system","slug":"glossary-writing-system","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The combination of a script and a set of usage conventions.","url":"articles/glossary-writing-system/","image":"articles/media/glossary/terms/writing_system/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/writing_system"},{"title":"X-height","slug":"glossary-x-height","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"The height of the lowercase characters that have no ascenders nor descenders, which indicates how tall or short the type appears.","url":"articles/glossary-x-height/","image":"articles/media/glossary/terms/x_height/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/x_height"},{"title":"Parametric Thick Stroke axis (XOPQ)","slug":"glossary-xopq-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A parametric axis for varying thick stroke weights, such as stems.","url":"articles/glossary-xopq-axis/","image":"articles/media/glossary/terms/xopq_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/xopq_axis"},{"title":"Rotation in X axis (XROT)","slug":"glossary-xrot-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to alter the letterforms so that they appear to rotate in the X dimension.","url":"articles/glossary-xrot-axis/","image":"articles/media/glossary/terms/xrot_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/xrot_axis"},{"title":"Parametric Counter Width axis (XTRA)","slug":"glossary-xtra-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A parametric axis for varying counter widths in the X dimension.","url":"articles/glossary-xtra-axis/","image":"articles/media/glossary/terms/xtra_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/xtra_axis"},{"title":"Year axis (YEAR)","slug":"glossary-year-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to show the effect of time — metaphorically — on the type used to set the text.","url":"articles/glossary-year-axis/","image":"articles/media/glossary/terms/year_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/year_axis"},{"title":"Vertical Element Alignment axis (YELA)","slug":"glossary-yela-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to align elements within modular typefaces’ glyphs to different positions in the Y dimension.","url":"articles/glossary-yela-axis/","image":"articles/media/glossary/terms/yela_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/yela_axis"},{"title":"Parametric Thin Stroke axis (YOPQ)","slug":"glossary-yopq-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A parametric axis for varying thin stroke weights, such as bars and hairlines.","url":"articles/glossary-yopq-axis/","image":"articles/media/glossary/terms/yopq_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/yopq_axis"},{"title":"Rotation in Y axis (YROT)","slug":"glossary-yrot-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to alter the letterforms so that they appear to rotate in the Y dimension.","url":"articles/glossary-yrot-axis/","image":"articles/media/glossary/terms/yrot_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/yrot_axis"},{"title":"Parametric Ascender Height axis (YTAS)","slug":"glossary-ytas-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A parametric axis for varying the height of lowercase ascenders.","url":"articles/glossary-ytas-axis/","image":"articles/media/glossary/terms/ytas_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/ytas_axis"},{"title":"Parametric Descender Depth axis (YTDE)","slug":"glossary-ytde-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A parametric axis for varying the depth of lowercase descenders.","url":"articles/glossary-ytde-axis/","image":"articles/media/glossary/terms/ytde_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/ytde_axis"},{"title":"Parametric Figure Height axis (YTFI)","slug":"glossary-ytfi-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A parametric axis for varying the height of figures.","url":"articles/glossary-ytfi-axis/","image":"articles/media/glossary/terms/ytfi_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/ytfi_axis"},{"title":"Parametric Lowercase Height axis (YTLC)","slug":"glossary-ytlc-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A parametric axis for varying the height of the lowercase.","url":"articles/glossary-ytlc-axis/","image":"articles/media/glossary/terms/ytlc_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/ytlc_axis"},{"title":"Parametric Uppercase Height axis (YTUC)","slug":"glossary-ytuc-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"A parametric axis for varying the heights of uppercase letterforms.","url":"articles/glossary-ytuc-axis/","image":"articles/media/glossary/terms/ytuc_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/ytuc_axis"},{"title":"Rotation in Z axis (ZROT)","slug":"glossary-zrot-axis","kind":"Glossary","topic":"Typography terms","authors":["Google Fonts Knowledge contributors"],"excerpt":"An axis found in some variable fonts that can be used to alter the letterforms so that they appear to rotate in the Z dimension.","url":"articles/glossary-zrot-axis/","image":"articles/media/glossary/terms/zrot_axis/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/glossary/zrot_axis"},{"title":"A checklist for choosing type","slug":"a-checklist-for-choosing-type","kind":"Lesson","topic":"Choosing type","authors":["Elliot Jay Stocks"],"excerpt":"A simple but thorough checklist to reference every time we need to choose a new typeface, with each item explained in detail.","url":"articles/a-checklist-for-choosing-type/","image":"articles/media/modules/choosing_type/lessons/a_checklist_for_choosing_type/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/a_checklist_for_choosing_type"},{"title":"Adding fonts to Google Docs and Slides","slug":"adding-fonts-to-google-docs","kind":"Lesson","topic":"Choosing type","authors":["Elliot Jay Stocks"],"excerpt":"Google’s Workspace apps, such as Docs, Sheets, and Slides, come with a selection of typefaces to choose from, accessible via the Font menu. But did you know you can actually add any font from the Google Fonts library to this menu, too?","url":"articles/adding-fonts-to-google-docs/","image":"articles/media/modules/choosing_type/lessons/adding_fonts_to_google_docs/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/adding_fonts_to_google_docs"},{"title":"Choosing reliable typefaces","slug":"choosing-reliable-typefaces","kind":"Lesson","topic":"Choosing type","authors":["Elliot Jay Stocks"],"excerpt":"Ideally, a reliable typeface should include language support, legible details, multiple weights and styles, and alternate characters.","url":"articles/choosing-reliable-typefaces/","image":"articles/media/modules/choosing_type/lessons/choosing_reliable_typefaces/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/choosing_reliable_typefaces"},{"title":"Choosing typefaces that have optical sizes","slug":"choosing-typefaces-that-have-optical-sizes","kind":"Lesson","topic":"Choosing type","authors":["Elliot Jay Stocks"],"excerpt":"Optical sizing refers to the practice of type foundries creating slightly different versions of a typeface intended to be used at different sizes.","url":"articles/choosing-typefaces-that-have-optical-sizes/","image":"articles/media/modules/choosing_type/lessons/choosing_typefaces_that_have_optical_sizes/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/choosing_typefaces_that_have_optical_sizes"},{"title":"Choosing web fonts: A beginner's all-in-one guide","slug":"choosing-web-fonts-beginners-guide","kind":"Lesson","topic":"Choosing type","authors":["Charles Berret"],"excerpt":"A beginners' guide to choosing web fonts.","url":"articles/choosing-web-fonts-beginners-guide/","image":"articles/media/modules/choosing_type/lessons/choosing_web_fonts_beginners_guide/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/choosing_web_fonts_beginners_guide"},{"title":"Emotive considerations for choosing typefaces","slug":"emotive-considerations-for-choosing-typefaces","kind":"Lesson","topic":"Choosing type","authors":["Elliot Jay Stocks"],"excerpt":"The emotional response to the shape of letterforms is a very personal experience, and when readers first see type, they react to it in an emotional way before anything else.","url":"articles/emotive-considerations-for-choosing-typefaces/","image":"articles/media/modules/choosing_type/lessons/emotive_considerations_for_choosing_typefaces/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/emotive_considerations_for_choosing_typefaces"},{"title":"Exploring typefaces with multiple weights or grades","slug":"exploring-typefaces-with-multiple-weights-or-grades","kind":"Lesson","topic":"Choosing type","authors":["Elliot Jay Stocks"],"excerpt":"There are many scenarios where multiple weights—if not multiple styles—are not just desired, but essential.","url":"articles/exploring-typefaces-with-multiple-weights-or-grades/","image":"articles/media/modules/choosing_type/lessons/exploring_typefaces_with_multiple_weights_or_grades/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/exploring_typefaces_with_multiple_weights_or_grades"},{"title":"Exploring width in type","slug":"exploring-width-in-type","kind":"Lesson","topic":"Choosing type","authors":["Elliot Jay Stocks"],"excerpt":"Multiple widths offer the typographer more ways to work with type without the need to use more than one typeface.","url":"articles/exploring-width-in-type/","image":"articles/media/modules/choosing_type/lessons/exploring_width_in_type/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/exploring_width_in_type"},{"title":"Exploring x-height & the em square","slug":"exploring-x-height-the-em-square","kind":"Lesson","topic":"Choosing type","authors":["Elliot Jay Stocks"],"excerpt":"When we swap fonts, or we introduce another font, there’s very often a slight change in layout. Let’s explore what’s going on.","url":"articles/exploring-x-height-the-em-square/","image":"articles/media/modules/choosing_type/lessons/exploring_x_height_the_em_square/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/exploring_x_height_the_em_square"},{"title":"Pairing typefaces","slug":"pairing-typefaces","kind":"Lesson","topic":"Choosing type","authors":["Elliot Jay Stocks"],"excerpt":"Once we’ve spent all that time and effort choosing a primary typeface for our project, we get to do it all over again for a secondary typeface.","url":"articles/pairing-typefaces/","image":"articles/media/modules/choosing_type/lessons/pairing_typefaces/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/pairing_typefaces"},{"title":"Pairing typefaces using the font matrix","slug":"pairing-typefaces-based-on-their-construction-using-the-font-matrix","kind":"Lesson","topic":"Choosing type","authors":["Oliver Schöndorfer"],"excerpt":"A detailed approach to combining typefaces based on their construction.","url":"articles/pairing-typefaces-based-on-their-construction-using-the-font-matrix/","image":"articles/media/modules/choosing_type/lessons/pairing_typefaces_based_on_their_construction_using_the_font_matrix/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/pairing_typefaces_based_on_their_construction_using_the_font_matrix"},{"title":"Pairing typefaces by the same type designer or type foundry","slug":"pairing-typefaces-by-the-same-type-designer-or-type-foundry","kind":"Lesson","topic":"Choosing type","authors":["Elliot Jay Stocks"],"excerpt":"Type designers often have certain stylistic ways of drawing letterforms, and certain technical ways of creating font files.","url":"articles/pairing-typefaces-by-the-same-type-designer-or-type-foundry/","image":"articles/media/modules/choosing_type/lessons/pairing_typefaces_by_the_same_type_designer_or_type_foundry/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/pairing_typefaces_by_the_same_type_designer_or_type_foundry"},{"title":"Pairing typefaces within a family & superfamily","slug":"pairing-typefaces-within-a-family-superfamily","kind":"Lesson","topic":"Choosing type","authors":["Elliot Jay Stocks"],"excerpt":"The advantage of staying within the family means there’s a shared consistency across every variation.","url":"articles/pairing-typefaces-within-a-family-superfamily/","image":"articles/media/modules/choosing_type/lessons/pairing_typefaces_within_a_family_superfamily/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/pairing_typefaces_within_a_family_superfamily"},{"title":"An alphabet for reading and writing","slug":"an-alphabet-for-reading-and-writing","kind":"Lesson","topic":"Designing hangeul","authors":["Darrell Penta"],"excerpt":"Part 4 in our in-depth look at the creation of Hangeul, the Korean alphabet.","url":"articles/an-alphabet-for-reading-and-writing/","image":"articles/media/modules/designing_hangeul/lessons/an_alphabet_for_reading_and_writing/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/an_alphabet_for_reading_and_writing"},{"title":"An introduction to Hangeul, the Korean alphabet","slug":"an-introduction-to-hangeul","kind":"Lesson","topic":"Designing hangeul","authors":["Darrell Penta"],"excerpt":"Part 1 in our in-depth look at the creation of Hangeul, the Korean alphabet.","url":"articles/an-introduction-to-hangeul/","image":"articles/media/modules/designing_hangeul/lessons/an_introduction_to_hangeul/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/an_introduction_to_hangeul"},{"title":"Designing for learnability","slug":"designing-for-learnability","kind":"Lesson","topic":"Designing hangeul","authors":["Darrell Penta"],"excerpt":"Part 2 in our in-depth look at the creation of Hangeul, the Korean alphabet.","url":"articles/designing-for-learnability/","image":"articles/media/modules/designing_hangeul/lessons/designing_for_learnability/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/designing_for_learnability"},{"title":"Lessons from Hangeul","slug":"lessons-from-hangeul","kind":"Lesson","topic":"Designing hangeul","authors":["Darrell Penta"],"excerpt":"Part 5 in our in-depth look at the creation of Hangeul, the Korean alphabet.","url":"articles/lessons-from-hangeul/","image":"articles/media/modules/designing_hangeul/lessons/lessons_from_hangeul/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/lessons_from_hangeul"},{"title":"Making the details matter","slug":"making-the-details-matter","kind":"Lesson","topic":"Designing hangeul","authors":["Darrell Penta"],"excerpt":"Part 3 in our in-depth look at the creation of Hangeul, the Korean alphabet.","url":"articles/making-the-details-matter/","image":"articles/media/modules/designing_hangeul/lessons/making_the_details_matter/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/making_the_details_matter"},{"title":"Display type","slug":"display-type","kind":"Lesson","topic":"History of type","authors":["John Boardley"],"excerpt":"The rise of display fonts in the 19th century, and the invention of the sans serif.","url":"articles/display-type/","image":"articles/media/modules/history_of_type/lessons/display_type/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/display_type"},{"title":"Fitting the line","slug":"fitting-the-line","kind":"Lesson","topic":"History of type","authors":["Micah Rich","Thomas Jockin"],"excerpt":"Type designers have long created complex typeface families of various weights and widths that allow a word of almost any length to fit on the same text line (i.e.; to “fit the line”). But only recently have we also had the benefit of variable fonts to make the task easier.","url":"articles/fitting-the-line/","image":"articles/media/modules/history_of_type/lessons/fitting_the_line/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/fitting_the_line"},{"title":"From metal to digital","slug":"from-metal-to-digital","kind":"Lesson","topic":"History of type","authors":["John Boardley"],"excerpt":"The 20th-century typographic revolution — from metal sorts to font files.","url":"articles/from-metal-to-digital/","image":"articles/media/modules/history_of_type/lessons/from_metal_to_digital/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/from_metal_to_digital"},{"title":"Justification & hyphenation","slug":"justification-hyphenation","kind":"Lesson","topic":"History of type","authors":["Micah Rich","Thomas Jockin"],"excerpt":"In western text, which reads left to right, justification and hyphenation are basic considerations for readability and clarity. But have you ever thought about how you can use them to create a look/feel that alludes to the literary culture of the past?","url":"articles/justification-hyphenation/","image":"articles/media/modules/history_of_type/lessons/justification_hyphenation/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/justification_hyphenation"},{"title":"Modern type","slug":"modern-type","kind":"Lesson","topic":"History of type","authors":["John Boardley"],"excerpt":"Bodoni and Didot, and the rise of the Modern high contrast style.","url":"articles/modern-type/","image":"articles/media/modules/history_of_type/lessons/modern_type/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/modern_type"},{"title":"The invention of type","slug":"the-invention-of-type","kind":"Lesson","topic":"History of type","authors":["John Boardley"],"excerpt":"The European advent of printing and the invention of fonts.","url":"articles/the-invention-of-type/","image":"articles/media/modules/history_of_type/lessons/the_invention_of_type/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/the_invention_of_type"},{"title":"The “tight not touching” style","slug":"the-tight-not-touching-style","kind":"Lesson","topic":"History of type","authors":["Micah Rich","Thomas Jockin"],"excerpt":"In the 1960s, the introduction of photo-typesetting made it possible to set type tighter than ever before. Over the next two decades, designers like Herb Lubalin and Tom Carnase used this new ability in letter spacing to create a (very cool) new aesthetic called tight-not-touching.","url":"articles/the-tight-not-touching-style/","image":"articles/media/modules/history_of_type/lessons/the_tight_not_touching_style/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/the_tight_not_touching_style"},{"title":"Transitional faces","slug":"transitional-faces","kind":"Lesson","topic":"History of type","authors":["John Boardley"],"excerpt":"The rise of roman fonts and the French typographic revolution.","url":"articles/transitional-faces/","image":"articles/media/modules/history_of_type/lessons/transitional_faces/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/transitional_faces"},{"title":"What have the Romans ever done for us?","slug":"what-have-the-romans-ever-done-for-us","kind":"Lesson","topic":"History of type","authors":["John Boardley"],"excerpt":"How roman fonts overtook blackletter to dominate European typography.","url":"articles/what-have-the-romans-ever-done-for-us/","image":"articles/media/modules/history_of_type/lessons/what_have_the_romans_ever_done_for_us/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/what_have_the_romans_ever_done_for_us"},{"title":"An overview of Latin type anatomy","slug":"an-overview-of-latin-type-anatomy","kind":"Lesson","topic":"Introducing type","authors":["Elliot Jay Stocks"],"excerpt":"A visual guide to the essential building blocks of typefaces that use the Latin script.","url":"articles/an-overview-of-latin-type-anatomy/","image":"articles/media/modules/introducing_type/lessons/an_overview_of_latin_type_anatomy/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/an_overview_of_latin_type_anatomy"},{"title":"Exploring punctuation","slug":"exploring-punctuation","kind":"Lesson","topic":"Introducing type","authors":["Elliot Jay Stocks"],"excerpt":"Punctuation matters: It conveys pause and effect to the reader, and designers should ensure the correct glyphs are rendered as—and when—required.","url":"articles/exploring-punctuation/","image":"articles/media/modules/introducing_type/lessons/exploring_punctuation/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/exploring_punctuation"},{"title":"How typefaces are designed & fonts are made","slug":"how-typefaces-are-designed-and-fonts-are-made","kind":"Lesson","topic":"Introducing type","authors":["Jamie Clarke"],"excerpt":"An overview of the type design process, from ideation and sketching right through to making fonts and releasing them.","url":"articles/how-typefaces-are-designed-and-fonts-are-made/","image":"articles/media/modules/introducing_type/lessons/how_typefaces_are_designed_and_fonts_are_made/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/how_typefaces_are_designed_and_fonts_are_made"},{"title":"Introducing alternate glyphs","slug":"introducing-alternate-glyphs","kind":"Lesson","topic":"Introducing type","authors":["Elliot Jay Stocks"],"excerpt":"The default characters we see in a typeface aren’t necessarily the only options available to us.","url":"articles/introducing-alternate-glyphs/","image":"articles/media/modules/introducing_type/lessons/introducing_alternate_glyphs/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/introducing_alternate_glyphs"},{"title":"Introducing color fonts","slug":"introducing-color-fonts","kind":"Lesson","topic":"Introducing type","authors":["Rod Sheeter"],"excerpt":"Color fonts allow the font to use many colors and to have an opinion about what those colors should be.","url":"articles/introducing-color-fonts/","image":"articles/media/modules/introducing_type/lessons/introducing_color_fonts/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/introducing_color_fonts"},{"title":"Introducing variable fonts","slug":"introducing-variable-fonts","kind":"Lesson","topic":"Introducing type","authors":["Elliot Jay Stocks"],"excerpt":"Variable fonts remove the explicit distinctions between different weights and styles, and put more typographic control in the hands of the user.","url":"articles/introducing-variable-fonts/","image":"articles/media/modules/introducing_type/lessons/introducing_variable_fonts/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/introducing_variable_fonts"},{"title":"Introducing weights & styles","slug":"introducing-weights-styles","kind":"Lesson","topic":"Introducing type","authors":["Elliot Jay Stocks"],"excerpt":"If we consider a typeface to be the “core” design, then different weights and styles could be said to be extensions of that design.","url":"articles/introducing-weights-styles/","image":"articles/media/modules/introducing_type/lessons/introducing_weights_styles/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/introducing_weights_styles"},{"title":"Making sense of typographic classifications","slug":"making-sense-of-typographic-classifications","kind":"Lesson","topic":"Introducing type","authors":["Elliot Jay Stocks"],"excerpt":"With so many typefaces in the world, searching for the right one can be a daunting task, but filtering helps.","url":"articles/making-sense-of-typographic-classifications/","image":"articles/media/modules/introducing_type/lessons/making_sense_of_typographic_classifications/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/making_sense_of_typographic_classifications"},{"title":"OpenType features in practice","slug":"open-type-features-in-practice","kind":"Lesson","topic":"Introducing type","authors":["Elliot Jay Stocks"],"excerpt":"When attempting to implement any OpenType feature, it’s important to ensure that it’s actually doable.","url":"articles/open-type-features-in-practice/","image":"articles/media/modules/introducing_type/lessons/open_type_features_in_practice/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/open_type_features_in_practice"},{"title":"Understanding numerals","slug":"understanding-numerals","kind":"Lesson","topic":"Introducing type","authors":["Elliot Jay Stocks"],"excerpt":"Numbers, like letters, can be conveyed in different ways with typography to communicate meaning.","url":"articles/understanding-numerals/","image":"articles/media/modules/introducing_type/lessons/understanding_numerals/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/understanding_numerals"},{"title":"Why care about typography?","slug":"why-care-about-typography","kind":"Lesson","topic":"Introducing type","authors":["Elliot Jay Stocks"],"excerpt":"Deliberate typeface choices and thoughtful typographic decisions serve to honor the content.","url":"articles/why-care-about-typography/","image":"articles/media/modules/introducing_type/lessons/why_care_about_typography/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/why_care_about_typography"},{"title":"How type influences readability","slug":"how-type-influences-readability","kind":"Lesson","topic":"Readability and accessibility","authors":["Hilary Palmen"],"excerpt":"Reading is what we do, and readability refers to qualities of a text that make reading easier. This includes content decisions, or format decisions, which help a reader to easily engage with and comprehend the message intended by the author.","url":"articles/how-type-influences-readability/","image":"articles/media/modules/readability_and_accessibility/lessons/how_type_influences_readability/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/how_type_influences_readability"},{"title":"Introducing accessibility in typography","slug":"introducing-accessibility-in-typography","kind":"Lesson","topic":"Readability and accessibility","authors":["Susanna Zaraysky"],"excerpt":"Making text accessible should be part of everyday practice. However, general typographic practices of optimizing legibility and readability don’t necessarily go all the way towards making text accessible.","url":"articles/introducing-accessibility-in-typography/","image":"articles/media/modules/readability_and_accessibility/lessons/introducing_accessibility_in_typography/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/introducing_accessibility_in_typography"},{"title":"Algonquian Syllabics","slug":"algonquian-syllabics","kind":"Lesson","topic":"The canadian syllabics","authors":["Kevin King"],"excerpt":"This article presents and describes the local orthographic requirements and typographic preferences for the nêhiyawêwin (Cree), Anishinaabemowin (Ojibwe), and iyuw iyimuun (Naskapi) Syllabics-using communities.","url":"articles/algonquian-syllabics/","image":"articles/media/modules/the_canadian_syllabics/lessons/algonquian_syllabics/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/algonquian_syllabics"},{"title":"An introduction to Syllabics typography","slug":"an-introduction-to-syllabics-typography","kind":"Lesson","topic":"The canadian syllabics","authors":["Kevin King"],"excerpt":"This article presents and describes the fundamental concepts that are inherent across all Syllabics typography.","url":"articles/an-introduction-to-syllabics-typography/","image":"articles/media/modules/the_canadian_syllabics/lessons/an_introduction_to_syllabics_typography/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/an_introduction_to_syllabics_typography"},{"title":"Dakelh (Carrier) Syllabics","slug":"dakelh-carrier-syllabics","kind":"Lesson","topic":"The canadian syllabics","authors":["Kevin King"],"excerpt":"This article presents and describes the local orthographic requirements and typographic preferences for the Dakelh (Carrier) Syllabics-using communities.","url":"articles/dakelh-carrier-syllabics/","image":"articles/media/modules/the_canadian_syllabics/lessons/dakelh_carrier_syllabics/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/dakelh_carrier_syllabics"},{"title":"Dene Syllabics","slug":"dene-syllabics","kind":"Lesson","topic":"The canadian syllabics","authors":["Kevin King"],"excerpt":"This article presents and describes the local orthographic requirements and typographic preferences for the Dene (Athabaskan) Syllabics-using communities.","url":"articles/dene-syllabics/","image":"articles/media/modules/the_canadian_syllabics/lessons/dene_syllabics/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/dene_syllabics"},{"title":"Inuktut Syllabics","slug":"inuktut-syllabics","kind":"Lesson","topic":"The canadian syllabics","authors":["Kevin King"],"excerpt":"This article presents and describes the local orthographic requirements and typographic preferences for the Inuktut (Inuktitut) communities who use Syllabics.","url":"articles/inuktut-syllabics/","image":"articles/media/modules/the_canadian_syllabics/lessons/inuktut_syllabics/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/inuktut_syllabics"},{"title":"CJK Typesetting Rules","slug":"cjk-typesetting-rules","kind":"Lesson","topic":"Type in china japan and korea","authors":["Min-Young Kim"],"excerpt":"There are four big differences in rules of typesetting between Latin and CJK fonts: Full-width versus monospaced, use of punctuation, balance of the type, and the existence of italic.","url":"articles/cjk-typesetting-rules/","image":"articles/media/modules/type_in_china_japan_and_korea/lessons/cjk_typesetting_rules/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/cjk_typesetting_rules"},{"title":"Japanese typography basics","slug":"japanese-typography-basics","kind":"Lesson","topic":"Type in china japan and korea","authors":["Min-Young Kim"],"excerpt":"Japanese typesetting is complicated due to the use of three different kinds of scripts in one language. This article explains the fundamentals, from the structure of Japanese script to the kerning system called Tsume.","url":"articles/japanese-typography-basics/","image":"articles/media/modules/type_in_china_japan_and_korea/lessons/japanese_typography_basics/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/japanese_typography_basics"},{"title":"The evolution of Hangeul type design","slug":"the-evolution-of-hangeul-type-design","kind":"Lesson","topic":"Type in china japan and korea","authors":["Min-Young Kim"],"excerpt":"The Korean script Hangeul is one of the youngest scripts, but the evolution was so fast and unique from other scripts. Let’s look at how Hangeul design was developed over the years.","url":"articles/the-evolution-of-hangeul-type-design/","image":"articles/media/modules/type_in_china_japan_and_korea/lessons/the_evolution_of_hangeul_type_design/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/the_evolution_of_hangeul_type_design"},{"title":"Type classification in CJK: Chinese","slug":"type-classification-in-cjk-chinese","kind":"Lesson","topic":"Type in china japan and korea","authors":["Lisa Huang"],"excerpt":"Here, we look at how CJK scripts are classified differently from Latin, and also from each other, with a focus on Chinese.","url":"articles/type-classification-in-cjk-chinese/","image":"articles/media/modules/type_in_china_japan_and_korea/lessons/type_classification_in_cjk_chinese/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/type_classification_in_cjk_chinese"},{"title":"Type classification in CJK: Japanese","slug":"type-classification-in-cjk-japanese","kind":"Lesson","topic":"Type in china japan and korea","authors":["Min-Young Kim"],"excerpt":"Here, we look at how CJK scripts are classified differently from Latin, and also from each other, with a focus on Japanese.","url":"articles/type-classification-in-cjk-japanese/","image":"articles/media/modules/type_in_china_japan_and_korea/lessons/type_classification_in_cjk_japanese/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/type_classification_in_cjk_japanese"},{"title":"Type classification in CJK: Korean","slug":"type-classification-in-cjk-korean","kind":"Lesson","topic":"Type in china japan and korea","authors":["Min-Young Kim"],"excerpt":"Here, we look at how CJK scripts are classified differently from Latin, and also from each other, with a focus on Korean.","url":"articles/type-classification-in-cjk-korean/","image":"articles/media/modules/type_in_china_japan_and_korea/lessons/type_classification_in_cjk_korean/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/type_classification_in_cjk_korean"},{"title":"Avoiding widows & orphans","slug":"avoiding-widows-orphans","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"Like so many things in typography, avoiding widows and orphans means breaking the rules a little.","url":"articles/avoiding-widows-orphans/","image":"articles/media/modules/using_type/lessons/avoiding_widows_orphans/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/avoiding_widows_orphans"},{"title":"Breaking the rules","slug":"breaking-the-rules","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"There are plenty of typesetting scenarios where the standard way of doing things can create undesirable visual effects.","url":"articles/breaking-the-rules/","image":"articles/media/modules/using_type/lessons/breaking_the_rules/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/breaking_the_rules"},{"title":"Choosing a suitable line height","slug":"choosing-a-suitable-line-height","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"Line height is a property so often left at its default value that it can be easily overlooked.","url":"articles/choosing-a-suitable-line-height/","image":"articles/media/modules/using_type/lessons/choosing_a_suitable_line_height/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/choosing_a_suitable_line_height"},{"title":"Designing with variable fonts in desktop apps","slug":"designing-with-variable-fonts-in-desktop-apps","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"Most desktop design apps’ implementation of variable fonts is fairly consistent, even across different developers.","url":"articles/designing-with-variable-fonts-in-desktop-apps/","image":"articles/media/modules/using_type/lessons/designing_with_variable_fonts_in_desktop_apps/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/designing_with_variable_fonts_in_desktop_apps"},{"title":"From type to logotype","slug":"from-type-to-logotype","kind":"Lesson","topic":"Using type","authors":["Tom Muller"],"excerpt":"From a sketch, to typeface selection, to incorporating a mark, to finalizing a full logo, let’s look at every step in the process.","url":"articles/from-type-to-logotype/","image":"articles/media/modules/using_type/lessons/from_type_to_logotype/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/from_type_to_logotype"},{"title":"How to make type feel authentic","slug":"how-to-make-type-feel-authentic","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"There are occasions when the uniformity of type strips it off authenticity, but with a few simple tricks, we can re-introduce the human element into our typography.","url":"articles/how-to-make-type-feel-authentic/","image":"articles/media/modules/using_type/lessons/how_to_make_type_feel_authentic/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/how_to_make_type_feel_authentic"},{"title":"Implementing OpenType features on the web","slug":"implementing-open-type-features-on-the-web","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"Once we’re ready to add OpenType features to our web typography, implementing them via CSS is a relatively straightforward affair.","url":"articles/implementing-open-type-features-on-the-web/","image":"articles/media/modules/using_type/lessons/implementing_open_type_features_on_the_web/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/implementing_open_type_features_on_the_web"},{"title":"Installing & managing fonts—including variable fonts","slug":"installing-and-managing-fonts","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"Building and maintaining a font collection on the computer you use for design work is an important part of life as a designer. However, there are a number of ways this process can be optimized—primarily by understanding where font files live, but also by proactively organizing your collection with font management software.","url":"articles/installing-and-managing-fonts/","image":"articles/media/modules/using_type/lessons/installing_and_managing_fonts/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/installing_and_managing_fonts"},{"title":"Introducing parametric axes","slug":"introducing-parametric-axes","kind":"Lesson","topic":"Using type","authors":["Dave Crossland"],"excerpt":"Learn what parametric axes are and how experts use them to finesse opaque (positive) and transparent (negative) shapes to solve various typographic challenges.","url":"articles/introducing-parametric-axes/","image":"articles/media/modules/using_type/lessons/introducing_parametric_axes/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/introducing_parametric_axes"},{"title":"Language support in fonts","slug":"language-support-in-fonts","kind":"Lesson","topic":"Using type","authors":["Material Design"],"excerpt":"Each language has its own nuances, and when we use different scripts, there are further typographic considerations to keep in mind.","url":"articles/language-support-in-fonts/","image":"articles/media/modules/using_type/lessons/language_support_in_fonts/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/language_support_in_fonts"},{"title":"Loading variable fonts on the web","slug":"loading-variable-fonts-on-the-web","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"Using a variable font on our website is straightforward, but let’s break down each step in the process so we can see how it differs from using traditional web fonts.","url":"articles/loading-variable-fonts-on-the-web/","image":"articles/media/modules/using_type/lessons/loading_variable_fonts_on_the_web/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/loading_variable_fonts_on_the_web"},{"title":"Manual kerning is rarely required","slug":"manual-kerning-is-rarely-required","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"The need for us designers to kern is actually quite rare, thanks to the diligent work of professional type designers.","url":"articles/manual-kerning-is-rarely-required/","image":"articles/media/modules/using_type/lessons/manual_kerning_is_rarely_required/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/manual_kerning_is_rarely_required"},{"title":"Self-hosting web fonts","slug":"self-hosting-web-fonts","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"It can sometimes be preferable to host the web fonts you use on your own server, and not all fonts are available on a font delivery service.","url":"articles/self-hosting-web-fonts/","image":"articles/media/modules/using_type/lessons/self_hosting_web_fonts/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/self_hosting_web_fonts"},{"title":"Styling type on the web with variable fonts","slug":"styling-type-on-the-web-with-variable-fonts","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"Whether loading variable fonts from a font delivery service or our own server, the actual styling of them via CSS is the same as standard, non-variable fonts.","url":"articles/styling-type-on-the-web-with-variable-fonts/","image":"articles/media/modules/using_type/lessons/styling_type_on_the_web_with_variable_fonts/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/styling_type_on_the_web_with_variable_fonts"},{"title":"Switching from static to variable fonts","slug":"switching-from-static-to-variable-fonts","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"Swapping out our static fonts for variable ones can be a useful way of dipping your toes into this new world. With the overall typographic system tried and tested, it’s just of a case of finessing our typography—and saving some data while we’re at it.","url":"articles/switching-from-static-to-variable-fonts/","image":"articles/media/modules/using_type/lessons/switching_from_static_to_variable_fonts/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/switching_from_static_to_variable_fonts"},{"title":"The complications of typographic size on the web","slug":"the-complications-of-typographic-size","kind":"Lesson","topic":"Using type","authors":["Nick Sherman"],"excerpt":"The process of establishing an appropriate font size for different elements is more complicated than it might seem at first, and, in the context of web design, it can be especially tricky to weigh all the factors involved for an ideal reader experience.","url":"articles/the-complications-of-typographic-size/","image":"articles/media/modules/using_type/lessons/the_complications_of_typographic_size/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/the_complications_of_typographic_size"},{"title":"The foundations of web typography","slug":"the-foundations-of-web-typography","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"An absolute beginner’s guide to setting type on the web, from CSS basics to implementing web fonts.","url":"articles/the-foundations-of-web-typography/","image":"articles/media/modules/using_type/lessons/the_foundations_of_web_typography/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/the_foundations_of_web_typography"},{"title":"Track carefully or not at all","slug":"track-carefully-or-not-at-all","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"Because tracking is a manual adjustment made to type, it should be approached with a great deal of caution.","url":"articles/track-carefully-or-not-at-all/","image":"articles/media/modules/using_type/lessons/track_carefully_or_not_at_all/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/track_carefully_or_not_at_all"},{"title":"Typesetting on a curved path","slug":"typesetting-on-a-curved-path","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks","Adam Twardoch"],"excerpt":"Most of the time when we set type, we do so on a straight line, but occasionally we need to manipulate the baseline so that it follows a curve. And while this is generally rare, it’s something to consider when using type in circular interfaces, like those found on smartwatches.","url":"articles/typesetting-on-a-curved-path/","image":"articles/media/modules/using_type/lessons/typesetting_on_a_curved_path/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/typesetting_on_a_curved_path"},{"title":"Understanding measure/line length","slug":"understanding-measure-line-length","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"There are certain things we can do as typographers to tame potentially chaotic re-flows, and offer users an optimal reading experience.","url":"articles/understanding-measure-line-length/","image":"articles/media/modules/using_type/lessons/understanding_measure_line_length/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/understanding_measure_line_length"},{"title":"Using web fonts","slug":"using-web-fonts","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"Loading font files, referencing them, and assigning weights and styles. Plus, some optimization techniques.","url":"articles/using-web-fonts/","image":"articles/media/modules/using_type/lessons/using_web_fonts/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/using_web_fonts"},{"title":"Using web fonts from a font delivery service","slug":"using-web-fonts-from-a-font-delivery-service","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"The easiest way to implement web fonts on a website is to use a font delivery service, so that most of the heavy lifting is done for us.","url":"articles/using-web-fonts-from-a-font-delivery-service/","image":"articles/media/modules/using_type/lessons/using_web_fonts_from_a_font_delivery_service/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/using_web_fonts_from_a_font_delivery_service"},{"title":"Vertical spacing & line-height in design systems","slug":"vertical-spacing-and-line-height-in-design-systems","kind":"Lesson","topic":"Using type","authors":["Sebastian Bailey"],"excerpt":"Discover how inconcistencies in the way that line height is calculated can lead to some headaches when maintaining a design system—and learn how to potentially overcome them.","url":"articles/vertical-spacing-and-line-height-in-design-systems/","image":"articles/media/modules/using_type/lessons/vertical_spacing_and_line_height_in_design_systems/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/vertical_spacing_and_line_height_in_design_systems"},{"title":"Working with hanging punctuation","slug":"working-with-hanging-punctuation","kind":"Lesson","topic":"Using type","authors":["Elliot Jay Stocks"],"excerpt":"Because punctuation takes up a space but does not usually fill that space, such marks can create unintended optical indentations.","url":"articles/working-with-hanging-punctuation/","image":"articles/media/modules/using_type/lessons/working_with_hanging_punctuation/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/working_with_hanging_punctuation"},{"title":"Designing for AR/VR","slug":"designing-for-ar-vr","kind":"Lesson","topic":"Using type in ar and vr","authors":["Niteesh Yadav"],"excerpt":"As we develop and experience more sophisticated augmented reality and virtual reality (AR/VR) applications, the introduction of more features and functions increases the complexity of information in front of the reader. Our existing typographic rules are not sufficient to address these new variables.","url":"articles/designing-for-ar-vr/","image":"articles/media/modules/using_type_in_ar_and_vr/lessons/designing_for_ar_vr/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/designing_for_ar_vr"},{"title":"Introducing AR/VR","slug":"introducing-ar-vr","kind":"Lesson","topic":"Using type in ar and vr","authors":["Niteesh Yadav"],"excerpt":"With the immersive worlds of augmented reality (AR) and virtual reality (VR), digital experiences extend beyond a flat, two-dimensional world and we interact with text in the three-dimensional space around us.","url":"articles/introducing-ar-vr/","image":"articles/media/modules/using_type_in_ar_and_vr/lessons/introducing_ar_vr/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/introducing_ar_vr"},{"title":"Spatial classification of typography in AR/VR","slug":"spatial-classification-of-typography-in-ar-vr","kind":"Lesson","topic":"Using type in ar and vr","authors":["Niteesh Yadav"],"excerpt":"Spatial classifications can help with considerations for choosing typefaces, setting text, and even designing typefaces for different applications—as well as picking the most appropriate rendering methods.","url":"articles/spatial-classification-of-typography-in-ar-vr/","image":"articles/media/modules/using_type_in_ar_and_vr/lessons/spatial_classification_of_typography_in_ar_vr/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/spatial_classification_of_typography_in_ar_vr"},{"title":"Technical challenges for typography in AR/VR","slug":"technical-challenges-for-typography-in-ar-vr","kind":"Lesson","topic":"Using type in ar and vr","authors":["Niteesh Yadav"],"excerpt":"The rendering of text in AR/VR applications still follows models from  the ’90s, but the challenges for good typography don’t end there.","url":"articles/technical-challenges-for-typography-in-ar-vr/","image":"articles/media/modules/using_type_in_ar_and_vr/lessons/technical_challenges_for_typography_in_ar_vr/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/technical_challenges_for_typography_in_ar_vr"},{"title":"Type selection for AR/VR","slug":"type-selection-for-ar-vr","kind":"Lesson","topic":"Using type in ar and vr","authors":["Niteesh Yadav"],"excerpt":"Let's focus on considerations to keep in mind when selecting Latin typefaces and setting type in AR/VR applications. This information can also feed into the design of new typefaces that are better suited for AR/VR.","url":"articles/type-selection-for-ar-vr/","image":"articles/media/modules/using_type_in_ar_and_vr/lessons/type_selection_for_ar_vr/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/type_selection_for_ar_vr"},{"title":"Factors that influence the efficiency of variable web fonts","slug":"factors-that-influence-the-efficiency-of-variable-web-fonts","kind":"Lesson","topic":"Using variable fonts on the web","authors":["Nick Sherman"],"excerpt":"Which specific font qualities make the biggest impact on efficiency?","url":"articles/factors-that-influence-the-efficiency-of-variable-web-fonts/","image":"articles/media/modules/using_variable_fonts_on_the_web/lessons/factors_that_influence_the_efficiency_of_variable_web_fonts/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/factors_that_influence_the_efficiency_of_variable_web_fonts"},{"title":"Interactive animations with variable fonts","slug":"interactive-animations-with-variable-fonts","kind":"Lesson","topic":"Using variable fonts on the web","authors":["Nick Sherman"],"excerpt":"Variable font animations can provide subtle effects for user interactions and visual semantics, or they can be used for more dramatic special effects.","url":"articles/interactive-animations-with-variable-fonts/","image":"articles/media/modules/using_variable_fonts_on_the_web/lessons/interactive_animations_with_variable_fonts/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/interactive_animations_with_variable_fonts"},{"title":"Optimizing typographic space with variable fonts","slug":"optimizing-typographic-space-with-variable-fonts","kind":"Lesson","topic":"Using variable fonts on the web","authors":["Nick Sherman"],"excerpt":"Variable fonts offer much more flexibility for typesetting in both printed and digital media, and this flexibility is especially beneficial in the context of responsive design.","url":"articles/optimizing-typographic-space-with-variable-fonts/","image":"articles/media/modules/using_variable_fonts_on_the_web/lessons/optimizing_typographic_space_with_variable_fonts/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/optimizing_typographic_space_with_variable_fonts"},{"title":"Variable fonts are here. Now what?","slug":"variable-fonts-are-here","kind":"Lesson","topic":"Using variable fonts on the web","authors":["Nick Sherman"],"excerpt":"What are the practical benefits of variable fonts in real-world design projects? And what are the implications of variable fonts’ flexibility in day-to-day design work?","url":"articles/variable-fonts-are-here/","image":"articles/media/modules/using_variable_fonts_on_the_web/lessons/variable_fonts_are_here/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/variable_fonts_are_here"},{"title":"Web font comparisons: variable vs. static","slug":"web-font-comparisons-variable-vs-static","kind":"Lesson","topic":"Using variable fonts on the web","authors":["Nick Sherman"],"excerpt":"How efficient are variable web fonts when compared to static fonts? As with most questions related to typography, the answer—for better or worse—is “it depends.”","url":"articles/web-font-comparisons-variable-vs-static/","image":"articles/media/modules/using_variable_fonts_on_the_web/lessons/web_font_comparisons_variable_vs_static/images/thumbnail.svg","original":"https://fonts.google.com/knowledge/lesson/web_font_comparisons_variable_vs_static"}]};
